                    "enum": ["researcher", "builder", "validator"],
                    "description": (
                        "Tool access profile. 'researcher' = read-only, "
                        "'builder' = can modify workflows, "
                        "'validator' = can execute and analyze."
                    ),
                },
                "tool_calls": {
