# Module-level state for active demo
_demo_state: dict = {
    "active": False,
    "scenario": None,
    "current_step_idx": 0,
    "started_at": None,
    "checkpoints": [],
}
_demo_lock = threading.Lock()


# ---------------------------------------------------------------------------
# Tool schemas
# ---------------------------------------------------------------------------

TOOLS: list[dict] = [
    {
        "name": "start_demo",
        "description": (
            "Start a guided demo scenario. Activates narration mode where "
            "the agent explains every action in artist-friendly terms. "
            "Available scenarios: model_swap, speed_run, controlnet_add, full_pipeline."
        ),
        "input_schema": {
            "type": "object",
            "properties": {
                "scenario": {
                    "type": "string",
                    "description": "Demo scenario name. Use 'list' to see all available scenarios.",
                },
            },
            "required": ["scenario"],
        },
    },
    {
        "name": "demo_checkpoint",
        "description": (
            "Mark a demo milestone. Summarizes what just happened and "
            "previews what comes next. Use for pacing during live demos."
        ),
        "input_schema": {
            "type": "object",
            "properties": {
                "step_completed": {
                    "type": "string",
                    "description": "ID of the step that was just completed.",
                },
                "notes": {
                    "type": "string",
                    "description": "Any additional notes about what happened in this step.",
                },
            },
            "required": ["step_completed"],
        },
    },
]


# ---------------------------------------------------------------------------
# Handlers
# ---------------------------------------------------------------------------

def _handle_start_demo(tool_input: dict) -> str:
    scenario_name = tool_input["scenario"]

    if scenario_name == "list":
        scenarios = []
        for name, sc in sorted(DEMO_SCENARIOS.items()):
            scenarios.append({
                "name": name,
                "title": sc["title"],
                "description": sc["description"],
                "audience": sc["audience"],
                "duration": sc["duration_estimate"],
                "steps": len(sc["steps"]),
            })
        return to_json({
            "available_scenarios": scenarios,
            "count": len(scenarios),
        })

    scenario = DEMO_SCENARIOS.get(scenario_name)
    if not scenario:
        return to_json({
            "error": f"Unknown scenario: {scenario_name}",
            "available": sorted(DEMO_SCENARIOS.keys()),
        })

    _demo_state["active"] = True
    _demo_state["scenario"] = scenario_name
    _demo_state["current_step_idx"] = 0
    _demo_state["started_at"] = time.time()
    _demo_state["checkpoints"] = []

    first_step = scenario["steps"][0]

    return to_json({
        "demo_started": True,
        "scenario": scenario_name,
        "title": scenario["title"],
        "description": scenario["description"],
        "total_steps": len(scenario["steps"]),
        "first_step": {
            "id": first_step["id"],
            "label": first_step["label"],
            "narration": first_step["narration"],
            "suggested_tools": first_step["suggested_tools"],
        },
        "message": (
            f"Demo '{scenario['title']}' started! "
            f"{len(scenario['steps'])} steps. "
            f"Estimated duration: {scenario['duration_estimate']}. "
            f"First up: {first_step['label']}."
        ),
    })


def _handle_demo_checkpoint(tool_input: dict) -> str:
    step_completed = tool_input["step_completed"]
    notes = tool_input.get("notes", "")

    if not _demo_state["active"]:
        return to_json({"error": "No active demo. Use start_demo first."})

    scenario = DEMO_SCENARIOS.get(_demo_state["scenario"])
    if not scenario:
        return to_json({"error": "Demo scenario not found."})

    # Record checkpoint
    _demo_state["checkpoints"].append({
        "step": step_completed,
        "notes": notes,
        "timestamp": time.time(),
    })

    # Advance to next step
    _demo_state["current_step_idx"] += 1
    step_idx = _demo_state["current_step_idx"]
    total = len(scenario["steps"])

    if step_idx >= total:
        # Demo complete
        elapsed = time.time() - _demo_state["started_at"]
        _demo_state["active"] = False

        return to_json({
            "demo_complete": True,
            "scenario": _demo_state["scenario"],
            "title": scenario["title"],
            "steps_completed": total,
            "elapsed_s": round(elapsed, 1),
            "elapsed_human": f"{int(elapsed // 60)}m {int(elapsed % 60)}s",
            "checkpoints": _demo_state["checkpoints"],
            "message": (
                f"Demo complete! '{scenario['title']}' finished in "
                f"{int(elapsed // 60)}m {int(elapsed % 60)}s."
            ),
        })

    # Show next step
    next_step = scenario["steps"][step_idx]
    progress = f"{step_idx}/{total}"

    return to_json({
        "checkpoint": step_completed,
        "progress": progress,
        "next_step": {
            "id": next_step["id"],
            "label": next_step["label"],
            "narration": next_step["narration"],
            "suggested_tools": next_step["suggested_tools"],
        },
        "elapsed_s": round(time.time() - _demo_state["started_at"], 1),
        "message": (
            f"[{progress}] {step_completed} complete. "
            f"Next: {next_step['label']}."
        ),
    })


# ---------------------------------------------------------------------------
# Dispatch
# ---------------------------------------------------------------------------

def handle(name: str, tool_input: dict) -> str:
    """Execute a demo tool call."""
    with _demo_lock:
        if name == "start_demo":
            return _handle_start_demo(tool_input)
        elif name == "demo_checkpoint":
            return _handle_demo_checkpoint(tool_input)
        else:
            return to_json({"error": f"Unknown demo tool: {name}"})

"""Command-line interface for the ComfyUI Agent."""

import atexit
import json
import logging
import signal
import threading

import typer
from rich.console import Console
from rich.panel import Panel

from .config import AGENT_MODEL, COMFYUI_URL, COMFYUI_DATABASE, ANTHROPIC_API_KEY, LOG_DIR
from .logging_config import setup_logging
from .tools import comfy_inspect, comfy_discover, session_tools

app = typer.Typer(
    help="ComfyUI Agent — AI co-pilot for ComfyUI workflows",
    no_args_is_help=True,
)
console = Console()


@app.command()
def run(
    session: str = typer.Option(
        None, "--session", "-s",
        help="Named session for memory persistence",
    ),
    verbose: bool = typer.Option(
        False, "--verbose", "-v",
        help="Show debug logging (API timing, tool execution, context management)",
    ),
):
    """Start an interactive agent session."""
    # Configure logging
    setup_logging(
        level=logging.DEBUG if verbose else logging.WARNING,
        log_file=LOG_DIR / "agent.log",
    )
    # Validate API key
    if not ANTHROPIC_API_KEY:
        console.print(
            "[red]ANTHROPIC_API_KEY not set.[/red]\n"
            "Setup steps:\n"
            "  1. Copy .env.example to .env\n"
            "  2. Get a key from https://console.anthropic.com/\n"
            "  3. Add: ANTHROPIC_API_KEY=sk-ant-...\n"
        )
        raise typer.Exit(1)

    # Show header
    console.print(Panel.fit(
        f"[bold blue]ComfyUI Agent[/bold blue]\n"
        f"Model: {AGENT_MODEL}\n"
        f"ComfyUI: {COMFYUI_URL}\n"
        f"Database: {COMFYUI_DATABASE}",
        title="ComfyUI Agent v0.2",
    ))

    # Load session context for system prompt injection
    session_context = None
    if session:
        console.print(f"[dim]Session: {session}[/dim]")
        # Restore session state
        load_result = json.loads(session_tools.handle("load_session", {"name": session}))
        if "error" not in load_result:
            console.print(f"[dim]Restored session from {load_result.get('saved_at', '?')}[/dim]")
            if load_result.get("workflow_restored"):
                console.print(f"[dim]Workflow loaded: {load_result.get('workflow_path')}[/dim]")
            if load_result.get("notes_count", 0) > 0:
                console.print(f"[dim]{load_result['notes_count']} note(s) from previous session[/dim]")
            # Build session context for system prompt
            session_context = {
                "name": session,
                "notes": load_result.get("notes", []),
                "workflow": {
                    "loaded_path": load_result.get("workflow_path"),
                    "format": load_result.get("workflow_format"),
                    "history_depth": 0,
                },
            }

    console.print("[dim]Type your question or command. 'quit' to exit.[/dim]\n")

    # Import here to avoid loading anthropic at CLI startup
    from .main import create_client, run_interactive, request_shutdown

    client = create_client()

    # Graceful shutdown: save session on SIGTERM or atexit
    _shutdown_done = threading.Event()

    def _save_and_exit(signum=None, frame=None):
        if _shutdown_done.is_set():
            return
        _shutdown_done.set()
        request_shutdown()
        if session:
            try:
                save_result = json.loads(
                    session_tools.handle("save_session", {"name": session})
                )
                if "saved" in save_result:
                    console.print(f"\n[dim]Session '{session}' saved.[/dim]")
            except Exception:
                pass

    signal.signal(signal.SIGTERM, _save_and_exit)
    atexit.register(
        lambda: _save_and_exit() if session and not _shutdown_done.is_set() else None
    )

    # Streaming callbacks
    _streamed_any = False

    def on_text_delta(text: str):
        nonlocal _streamed_any
        _streamed_any = True
        print(text, end="", flush=True)

    def on_tool_call(name: str, inp: dict):
        nonlocal _streamed_any
        if _streamed_any:
            print()  # Newline after streamed text
            _streamed_any = False
        inp_summary = json.dumps(inp, default=str, sort_keys=True)
        if len(inp_summary) > 80:
            inp_summary = inp_summary[:77] + "..."
        console.print(f"  [dim]-> {name}({inp_summary})[/dim]")

    def on_stream_end():
        nonlocal _streamed_any
        if _streamed_any:
            print()  # Final newline after streamed text
            _streamed_any = False

    def on_user_input() -> str | None:
        try:
            return console.input("[bold cyan]> [/bold cyan]")
        except (KeyboardInterrupt, EOFError):
            console.print()
            return None

    run_interactive(
        client,
        session_context=session_context,
        on_text_delta=on_text_delta,
        on_tool_call=on_tool_call,
        on_stream_end=on_stream_end,
        on_user_input=on_user_input,
    )

    # Save session on normal exit (atexit handles abnormal exit)
    _save_and_exit()

    console.print("\n[dim]Goodbye![/dim]")


