"""Tool registry for the ComfyUI SUPER DUPER Agent.

Each tool module exports:
  TOOLS: list[dict]    -- Anthropic tool schemas
  handle(name, input)  -- Execute a tool call, return result string

Intelligence layers (41 tools) + Brain layer (20 tools) = 61 tools total.
Brain tools are lazily imported to avoid circular dependencies
(brain modules import _util from this package).
"""

import logging

from . import comfy_api, comfy_inspect, workflow_parse, workflow_patch, comfy_execute, comfy_discover, session_tools, workflow_templates, civitai_api, model_compat

log = logging.getLogger(__name__)

_MODULES = (comfy_api, comfy_inspect, workflow_parse, workflow_patch, comfy_execute, comfy_discover, session_tools, workflow_templates, civitai_api, model_compat)

# Intelligence layer tool schemas
_LAYER_TOOLS: list[dict] = []
for _mod in _MODULES:
    _LAYER_TOOLS.extend(_mod.TOOLS)

# Map tool name -> handler module (intelligence layers)
_HANDLERS = {}
for _mod in _MODULES:
    for _tool in _mod.TOOLS:
        _HANDLERS[_tool["name"]] = _mod

# Brain tools are loaded lazily to break the circular import
_brain_loaded = False
_BRAIN_TOOL_NAMES: set[str] = set()


def _ensure_brain():
    """Lazily load brain layer tools."""
    global _brain_loaded, _BRAIN_TOOL_NAMES
    if _brain_loaded:
        return
    from ..brain import ALL_BRAIN_TOOLS
    _BRAIN_TOOL_NAMES.update(t["name"] for t in ALL_BRAIN_TOOLS)
    _brain_loaded = True


def _get_all_tools() -> list[dict]:
    """Get all tool schemas (intelligence + brain layers)."""
    _ensure_brain()
    from ..brain import ALL_BRAIN_TOOLS
    return _LAYER_TOOLS + list(ALL_BRAIN_TOOLS)


# Public API — ALL_TOOLS is a property-like accessor
class _ToolList(list):
    """Lazy tool list that includes brain tools on first access."""
    _initialized = False

    def _init_once(self):
        if not self._initialized:
            self._initialized = True
            self.extend(_LAYER_TOOLS)
            try:
                from ..brain import ALL_BRAIN_TOOLS
                self.extend(ALL_BRAIN_TOOLS)
            except ImportError:
                log.warning("Brain layer not available")

    def __iter__(self):
        self._init_once()
        return super().__iter__()

    def __len__(self):
        self._init_once()
        return super().__len__()

    def __getitem__(self, idx):
        self._init_once()
        return super().__getitem__(idx)


ALL_TOOLS = _ToolList()


def handle(name: str, tool_input: dict, *, session_id: str | None = None) -> str:
    """Dispatch a tool call to the right handler.

    Args:
        name: Tool name to dispatch.
        tool_input: Tool arguments dict.
        session_id: Optional session ID for workflow state isolation.
                    Currently unused (default session), but enables future
                    multi-session MCP usage.
    """
    # Check brain tools (lazy loaded)
    _ensure_brain()
    if name in _BRAIN_TOOL_NAMES:
        from ..brain import handle as handle_brain
        return handle_brain(name, tool_input)

    # Intelligence layer tools
    mod = _HANDLERS.get(name)
    if mod is None:
        log.warning("Unknown tool called: %s", name)
        return f"Unknown tool: {name}"
    try:
        return mod.handle(name, tool_input)
    except Exception as e:
        log.error("Unhandled error in tool %s", name, exc_info=True)
        from ._util import to_json
        return to_json({"error": f"Internal error in {name}: {type(e).__name__}: {e}"})

"""Shared utilities for tool modules.

He2025 alignment: deterministic JSON serialization ensures
same inputs -> same outputs across sessions and runs.
"""

import json as _json
from pathlib import Path

# Directories that tools are allowed to read/write within.
# Populated lazily from config to avoid circular imports.
_SAFE_DIRS: list[Path] | None = None

_BLOCKED_PREFIXES = (
    "C:\\Windows", "C:\\Program Files", "C:\\ProgramData",
    "/etc", "/usr", "/bin", "/sbin", "/var", "/root",
)


def _get_safe_dirs() -> list[Path]:
    """Lazily load safe directories from config."""
    global _SAFE_DIRS
    if _SAFE_DIRS is None:
        from ..config import (
            COMFYUI_DATABASE, PROJECT_DIR, SESSIONS_DIR, WORKFLOWS_DIR,
        )
        _SAFE_DIRS = [
            COMFYUI_DATABASE.resolve(),
            PROJECT_DIR.resolve(),
            SESSIONS_DIR.resolve(),
            WORKFLOWS_DIR.resolve(),
        ]
    return _SAFE_DIRS


def validate_path(path_str: str, *, must_exist: bool = False) -> str | None:
    """Validate a file path is safe for tool access.

    Returns None if valid, or an error message string if invalid.
    Rejects path traversal attacks and access to system directories.
    """
    try:
        p = Path(path_str).resolve()
    except (OSError, ValueError) as e:
        return f"Invalid path: {e}"

    # Block system directories
    p_str = str(p)
    for prefix in _BLOCKED_PREFIXES:
        if p_str.startswith(prefix):
            return "Access denied: path is in a protected system directory"

    # Check against allowed directories
    safe_dirs = _get_safe_dirs()
    in_safe_dir = any(
        p_str.startswith(str(sd)) for sd in safe_dirs
    )
    # Also allow temp directories (pytest tmp_path, system temp)
    import tempfile
    temp_dir = Path(tempfile.gettempdir()).resolve()
    if p_str.startswith(str(temp_dir)):
        in_safe_dir = True

    if not in_safe_dir:
        return (
            f"Access denied: path '{path_str}' is outside allowed directories. "
            f"Allowed: ComfyUI database, project dir, sessions, workflows."
        )

    if must_exist and not p.exists():
        return f"File not found: {path_str}"

    return None


def to_json(obj, **kwargs) -> str:
    """Serialize to JSON with deterministic key ordering."""
    kwargs.setdefault("sort_keys", True)
    return _json.dumps(obj, **kwargs)

"""Tests for brain/demo.py — guided demo walkthroughs."""

import json

import pytest

from agent.brain import demo


@pytest.fixture(autouse=True)
def reset_demo_state():
    """Reset demo state between tests."""
    demo._demo_state.update({
        "active": False,
        "scenario": None,
        "current_step_idx": 0,
        "started_at": None,
        "checkpoints": [],
    })
    yield


class TestStartDemo:
    def test_list_scenarios(self):
        result = json.loads(demo.handle("start_demo", {"scenario": "list"}))
        assert result["count"] >= 4
        names = [s["name"] for s in result["available_scenarios"]]
        assert "model_swap" in names
        assert "speed_run" in names
        assert "controlnet_add" in names
        assert "full_pipeline" in names

    def test_start_model_swap(self):
        result = json.loads(demo.handle("start_demo", {"scenario": "model_swap"}))
        assert result["demo_started"] is True
        assert result["scenario"] == "model_swap"
        assert result["total_steps"] == 4
        assert result["first_step"]["id"] == "analyze"

    def test_start_speed_run(self):
        result = json.loads(demo.handle("start_demo", {"scenario": "speed_run"}))
        assert result["demo_started"] is True
        assert result["title"] == "Making It Fast"

    def test_start_unknown(self):
        result = json.loads(demo.handle("start_demo", {"scenario": "nonexistent"}))
        assert "error" in result
        assert "available" in result

    def test_demo_state_activated(self):
        demo.handle("start_demo", {"scenario": "model_swap"})
        assert demo._demo_state["active"] is True
        assert demo._demo_state["scenario"] == "model_swap"


class TestDemoCheckpoint:
    def test_checkpoint_no_demo(self):
        result = json.loads(demo.handle("demo_checkpoint", {"step_completed": "test"}))
        assert "error" in result

    def test_checkpoint_advances(self):
        demo.handle("start_demo", {"scenario": "model_swap"})
        result = json.loads(demo.handle("demo_checkpoint", {
            "step_completed": "analyze",
            "notes": "Found SD 1.5 workflow with 30 steps",
        }))
        assert result["checkpoint"] == "analyze"
        assert result["next_step"]["id"] == "find_upgrade"
        assert "1/4" in result["progress"]

    def test_checkpoint_completes_demo(self):
        demo.handle("start_demo", {"scenario": "model_swap"})
        # Complete all 4 steps
        steps = ["analyze", "find_upgrade", "apply_swap", "compare"]
        for i, step in enumerate(steps):
            result = json.loads(demo.handle("demo_checkpoint", {
                "step_completed": step,
            }))

        assert result["demo_complete"] is True
        assert result["steps_completed"] == 4
        assert "elapsed_human" in result

    def test_checkpoint_records_history(self):
        demo.handle("start_demo", {"scenario": "model_swap"})
        demo.handle("demo_checkpoint", {
            "step_completed": "analyze",
            "notes": "test note",
        })
        assert len(demo._demo_state["checkpoints"]) == 1
        assert demo._demo_state["checkpoints"][0]["notes"] == "test note"


class TestDemoScenarios:
    """Verify all scenarios have valid structure."""

    def test_all_scenarios_have_required_fields(self):
        for name, scenario in demo.DEMO_SCENARIOS.items():
            assert "title" in scenario, f"{name} missing title"
            assert "description" in scenario, f"{name} missing description"
            assert "steps" in scenario, f"{name} missing steps"
            assert len(scenario["steps"]) >= 3, f"{name} has too few steps"

    def test_all_steps_have_required_fields(self):
        for name, scenario in demo.DEMO_SCENARIOS.items():
            for step in scenario["steps"]:
                assert "id" in step, f"{name}/{step} missing id"
                assert "label" in step, f"{name}/{step} missing label"
                assert "narration" in step, f"{name}/{step} missing narration"
                assert "suggested_tools" in step, f"{name}/{step} missing suggested_tools"

    def test_scenario_durations_present(self):
        for name, scenario in demo.DEMO_SCENARIOS.items():
            assert "duration_estimate" in scenario, f"{name} missing duration_estimate"

